/**
 * Deterministic fix snippets (plan 041 Part A, Slice 2). Never generated by
 * the model: classification and template text are code-owned per rule id,
 * same discipline as the remediation prose beside it.
 *
 * `fixed`: the correct markup or config is a known shape independent of the
 * page's own content (an attribute to add, a header line, a tag to remove).
 * `template` may reference `{{selector}}` and `{{resourceUrl}}`, filled in
 * deterministically from the finding's own `FindingElement` by
 * `interpolateSnippet` in index.ts, never by the model.
 *
 * `fill-in-blank`: the correct shape needs real content only the client can
 * supply (alt text, a page title, a phone number). `template` shows that
 * shape with a literal placeholder such as `<votre texte ici>`; it is never
 * interpolated with the finding's own captured content, since substituting
 * an already-wrong value into a "write better copy" template adds noise, not
 * help (brainstorm finding, docs/product/fix-snippets-and-scorecard-brainstorm.md).
 *
 * `not-applicable`: the finding is site-wide, behavioral, or about existing
 * content having an unknown defect (an invalid value, a stale file); no
 * generic template can localize the fix to one element.
 */
export type FixSnippet =
  | { kind: 'fixed'; template: string }
  | { kind: 'fill-in-blank'; template: string }
  | { kind: 'not-applicable' };

export interface RemediationEntry {
  text: string;
  snippet: FixSnippet;
}
